/* WellStream Platform — Shared Styles */
:root {
  --navy: #15295A;
  --navy-dark: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #1e3a6e;
  --green: #6CC24A;
  --green-light: #7dd95a;
  --gray-dark: #3C424B;
  --gray-mid: #5a6270;
  --gray-light: #8a9ab0;
  --white: #ffffff;
  --off-white: #f0f4f8;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --text-muted: #9aaec4;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--navy-dark);
  color: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.2rem; }

p { color: var(--text-muted); line-height: 1.8; }

a { color: var(--green); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--green-light); }

.section-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.75rem;
  display: block;
}

/* ===== LAYOUT ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.section { padding: 5rem 0; }
.section-dark { background: var(--navy-dark); }
.section-mid { background: var(--navy-mid); }
.section-navy { background: var(--navy); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 4px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  text-decoration: none;
}

.btn-primary {
  background: var(--green);
  color: var(--navy-dark);
}
.btn-primary:hover { background: var(--green-light); color: var(--navy-dark); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(108,194,74,0.35); }

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}
.btn-outline:hover { border-color: var(--green); color: var(--green); background: rgba(108,194,74,0.08); }

.btn-ghost {
  background: transparent;
  color: var(--green);
  padding-left: 0;
}
.btn-ghost:hover { color: var(--green-light); }
.btn-ghost::after { content: ' →'; }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.3s;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--white);
}

.nav-logo-mark {
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1rem;
  color: var(--navy-dark);
}

.nav-logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.nav-logo-text span { color: var(--green); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
}

.nav-links li { position: relative; }

.nav-links a {
  color: rgba(255,255,255,0.8);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 0.875rem;
  border-radius: 4px;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.nav-links a:hover { color: var(--white); background: rgba(255,255,255,0.06); }

.nav-dropdown-trigger::after { content: ' ▾'; font-size: 0.7rem; opacity: 0.7; }

.nav-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}

.nav-links li:hover .nav-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown a {
  display: block;
  padding: 0.6rem 1rem;
  color: rgba(255,255,255,0.75);
  font-size: 0.85rem;
  border-radius: 4px;
}
.nav-dropdown a:hover { color: var(--white); background: rgba(108,194,74,0.12); }

.nav-cta { display: flex; align-items: center; gap: 1rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.hamburger span { display: block; width: 24px; height: 2px; background: var(--white); border-radius: 2px; transition: all 0.3s; }

/* ===== HERO ===== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--navy-dark) 0%, #0a1628 50%, #0d1f3c 100%);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
}

.hero-glow {
  position: absolute;
  width: 800px;
  height: 800px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
  top: -200px;
  right: -200px;
  pointer-events: none;
}

.hero-content { position: relative; z-index: 1; padding-top: 68px; }
.hero .container { padding-top: 4rem; padding-bottom: 4rem; }

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.3);
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.4rem 1rem;
  border-radius: 100px;
  margin-bottom: 1.5rem;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.85) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  max-width: 580px;
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: 2.5rem;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 3rem;
  margin-top: 4rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.hero-stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}
.hero-stat-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.25rem; }

/* Sub-page hero */
.page-hero {
  padding: 8rem 0 4rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.03) 1px, transparent 1px);
  background-size: 50px 50px;
}
.page-hero .container { position: relative; z-index: 1; }
.page-hero h1 { max-width: 700px; margin-bottom: 1rem; }
.page-hero p { max-width: 580px; font-size: 1.1rem; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(90deg, var(--green) 0%, #4a9932 100%);
  padding: 1.25rem 0;
}
.featured-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.featured-banner-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.6);
}
.featured-banner-product {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy-dark);
}
.featured-banner-tagline { color: rgba(0,0,0,0.7); font-size: 0.9rem; }
.featured-banner .btn {
  background: var(--navy-dark);
  color: var(--white);
  font-size: 0.85rem;
  padding: 0.6rem 1.5rem;
}
.featured-banner .btn:hover { background: var(--navy); }

/* ===== CARDS ===== */
.card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  padding: 2rem;
  transition: all 0.3s;
}
.card:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(108,194,74,0.25);
  transform: translateY(-3px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--green);
  font-size: 1.4rem;
}

.card h4 { margin-bottom: 0.5rem; }
.card p { font-size: 0.9rem; }

/* ===== GRIDS ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* ===== SECTION HEADER ===== */
.section-header { margin-bottom: 3.5rem; }
.section-header.centered { text-align: center; }
.section-header h2 { margin-bottom: 1rem; }
.section-header p { max-width: 640px; font-size: 1.05rem; }
.section-header.centered p { margin: 0 auto; }

/* ===== USE CASES ===== */
.use-case-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.75rem;
  cursor: pointer;
  transition: all 0.3s;
  position: relative;
  overflow: hidden;
}
.use-case-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform 0.3s;
}
.use-case-card:hover::before { transform: scaleX(1); }
.use-case-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
}
.use-case-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.use-case-card h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.use-case-card p { font-size: 0.85rem; }

/* ===== PLATFORM DIAGRAM ===== */
.platform-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  margin-top: 2rem;
}

.diagram-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  position: relative;
}

.diagram-pillars::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(108,194,74,0.4), rgba(108,194,74,0.4), transparent);
  transform: translateY(-50%);
  z-index: 0;
}

.pillar {
  text-align: center;
  padding: 2rem 1.5rem;
  position: relative;
  z-index: 1;
}

.pillar-node {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--navy-dark);
  border: 3px solid var(--green);
  margin: 0 auto 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  position: relative;
  box-shadow: 0 0 24px rgba(108,194,74,0.25);
}

.pillar-node::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(108,194,74,0.2);
}

.pillar h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.pillar p { font-size: 0.85rem; }

.diagram-center-label {
  text-align: center;
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.diagram-center-label h3 { color: var(--white); }
.diagram-center-label span {
  display: inline-block;
  margin-top: 0.5rem;
  background: rgba(108,194,74,0.12);
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.3rem 1rem;
  border-radius: 100px;
  letter-spacing: 0.05em;
}

/* ===== INDUSTRY TABS ===== */
.tabs-container { margin-top: 1rem; }
.tabs-nav {
  display: flex;
  gap: 0.25rem;
  background: rgba(255,255,255,0.04);
  border-radius: 8px;
  padding: 0.35rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.tab-btn {
  padding: 0.6rem 1.25rem;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,0.06); }
.tab-btn.active {
  background: var(--green);
  color: var(--navy-dark);
  font-weight: 700;
}

.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.industry-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}
.industry-content h3 { margin-bottom: 1rem; }
.industry-content p { margin-bottom: 1.5rem; }

.industry-products {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.industry-product-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 6px;
  padding: 0.5rem 0.875rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
}

/* ===== CULTURE SECTION ===== */
.culture-section {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.07) 0%, transparent 70%);
  bottom: -200px; left: -100px;
}

.culture-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.culture-visual {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem 2rem;
  text-align: center;
  position: relative;
}

.culture-stat-ring {
  width: 160px;
  height: 160px;
  margin: 0 auto 1.5rem;
  position: relative;
}

.culture-stat-ring svg { transform: rotate(-90deg); }
.culture-stat-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-top: 1.5rem;
}
.client-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.15);
  border-radius: 6px;
  padding: 0.4rem;
  font-size: 0.7rem;
  color: var(--green);
  text-align: center;
  font-weight: 600;
}

/* ===== RENEWABLES CTA ===== */
.renewables-cta {
  background: linear-gradient(135deg, #0d3b1e 0%, #0a2d16 100%);
  border-top: 1px solid rgba(108,194,74,0.2);
  border-bottom: 1px solid rgba(108,194,74,0.2);
}
.renewables-inner {
  display: flex;
  align-items: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.renewables-icon {
  font-size: 4rem;
  flex-shrink: 0;
}
.renewables-text { flex: 1; min-width: 280px; }
.renewables-text h3 { color: var(--green); margin-bottom: 0.75rem; }

/* ===== PLATFORM BENEFITS ===== */
.benefit-item {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background 0.2s;
}
.benefit-item:last-child { border-bottom: none; }
.benefit-item:hover { background: rgba(255,255,255,0.02); border-radius: 8px; }

.benefit-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}
.benefit-text h4 { margin-bottom: 0.375rem; }
.benefit-text p { font-size: 0.9rem; }

/* ===== STATS CIRCLES ===== */
.stats-section { padding: 4rem 0; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.stat-circle-wrapper {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  transition: all 0.3s;
}
.stat-circle-wrapper:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
}

.stat-circle {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  margin: 0 auto 1.5rem;
  background: conic-gradient(var(--green) var(--pct), rgba(255,255,255,0.06) 0deg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.stat-circle::before {
  content: '';
  position: absolute;
  inset: 12px;
  border-radius: 50%;
  background: var(--navy-dark);
}

.stat-circle-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--white);
  display: block;
}

.stat-circle-label { font-size: 1rem; font-weight: 600; margin-bottom: 0.375rem; }
.stat-circle-desc { font-size: 0.85rem; color: var(--text-muted); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline-item {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline-item:last-child { border-bottom: none; }

.timeline-duration {
  min-width: 130px;
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--green);
}

.timeline-info { flex: 1; }
.timeline-info h4 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.timeline-info p { font-size: 0.85rem; }

.timeline-bar-wrapper {
  flex: 2;
  max-width: 400px;
}
.timeline-bar-bg {
  background: rgba(255,255,255,0.06);
  border-radius: 100px;
  height: 8px;
  overflow: hidden;
}
.timeline-bar-fill {
  height: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, var(--green), var(--green-light));
  transition: width 1s ease;
}

/* ===== ACCORDION ===== */
.accordion { border-radius: 12px; overflow: hidden; border: 1px solid rgba(255,255,255,0.08); }

.accordion-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: rgba(255,255,255,0.02);
  border: none;
  color: var(--white);
  font-size: 1.05rem;
  font-weight: 600;
  padding: 1.5rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: background 0.2s;
  font-family: inherit;
  text-align: left;
}
.accordion-header:hover { background: rgba(255,255,255,0.05); }
.accordion-header.open { background: rgba(108,194,74,0.08); color: var(--green); }

.accordion-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.3s;
  font-size: 0.85rem;
}
.accordion-header.open .accordion-icon { transform: rotate(45deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}
.accordion-body-inner {
  padding: 0 2rem 1.75rem;
  color: var(--text-muted);
  line-height: 1.8;
}

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  position: relative;
  overflow: hidden;
}

.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
}

.lifecycle-step {
  text-align: center;
  padding: 1.5rem;
  min-width: 140px;
}

.lifecycle-step-node {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 2px solid var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin: 0 auto 1rem;
  background: rgba(108,194,74,0.08);
  position: relative;
}

.lifecycle-arrow {
  color: rgba(108,194,74,0.5);
  font-size: 1.5rem;
  flex-shrink: 0;
  padding: 0 0.5rem;
  align-self: center;
  margin-bottom: 2.5rem;
}

.lifecycle-step h5 { font-size: 0.85rem; margin-bottom: 0.25rem; }
.lifecycle-step p { font-size: 0.75rem; }

.lifecycle-tracks {
  margin-top: 3rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 2.5rem;
}
.lifecycle-track {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
}
.lifecycle-track-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.lifecycle-track h4 { font-size: 0.95rem; margin-bottom: 0.5rem; }
.lifecycle-track p { font-size: 0.8rem; }

/* ===== TESTIMONIALS ===== */
.testimonial-carousel { position: relative; overflow: hidden; }

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--white);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '"';
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
  font-size: 5rem;
  color: rgba(108,194,74,0.15);
  font-style: normal;
  line-height: 1;
}

.testimonial-author {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--green);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.carousel-dot.active { background: var(--green); transform: scale(1.3); }

/* ===== SECURITY ===== */
.security-feature {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  transition: all 0.3s;
  margin-bottom: 1rem;
}
.security-feature:hover {
  border-color: rgba(108,194,74,0.25);
  background: rgba(108,194,74,0.04);
  transform: translateX(4px);
}
.security-feature:last-child { margin-bottom: 0; }

.security-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  color: var(--green);
}

.security-text h4 { margin-bottom: 0.4rem; }
.security-text p { font-size: 0.9rem; }

.soc-badges {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.soc-badge {
  background: rgba(255,255,255,0.03);
  border: 2px solid rgba(108,194,74,0.3);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  text-align: center;
}
.soc-badge-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.soc-badge p { font-size: 0.875rem; }

/* ===== INTEGRATION TABS ===== */
.integration-tabs-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}

.integration-tab-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.integration-visual {
  background: var(--navy-dark);
  border-radius: 12px;
  padding: 2rem;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.06);
}

.etl-flow {
  width: 100%;
}
.etl-block {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  text-align: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.etl-arrow {
  text-align: center;
  color: rgba(108,194,74,0.5);
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.api-endpoints {
  width: 100%;
}
.api-endpoint {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.875rem;
  background: rgba(255,255,255,0.03);
  border-radius: 6px;
  margin-bottom: 0.5rem;
  font-size: 0.8rem;
  font-family: 'Courier New', monospace;
}
.api-method {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 3px;
  min-width: 44px;
  text-align: center;
}
.api-method.get { background: rgba(108,194,74,0.2); color: var(--green); }
.api-method.post { background: rgba(0,180,216,0.2); color: var(--accent-blue); }
.api-endpoint-path { color: var(--text-muted); }

.dashboard-preview {
  width: 100%;
}
.dashboard-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.dashboard-widget {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 8px;
  padding: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}
.dashboard-widget-value {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.2rem;
}

/* ===== ETL BENEFITS ===== */
.etl-benefits-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.25rem; }
.etl-benefit {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: all 0.3s;
}
.etl-benefit:hover { border-color: rgba(108,194,74,0.25); background: rgba(108,194,74,0.04); }
.etl-check {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.875rem;
  flex-shrink: 0;
  margin-top: 2px;
}
.etl-benefit h4 { font-size: 0.95rem; margin-bottom: 0.35rem; }
.etl-benefit p { font-size: 0.85rem; }

/* ===== DEMO FORM ===== */
.demo-layout {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 4rem;
  align-items: start;
}

.demo-form-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2.5rem;
}

.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
.form-field { display: flex; flex-direction: column; gap: 0.4rem; }
.form-field.full { grid-column: 1 / -1; }

.form-label {
  font-size: 0.825rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  letter-spacing: 0.02em;
}

.form-input, .form-select, .form-textarea {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  color: var(--white);
  font-size: 0.9rem;
  padding: 0.75rem 1rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  font-family: inherit;
  width: 100%;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(108,194,74,0.12);
}
.form-input::placeholder, .form-textarea::placeholder { color: var(--text-muted); }
.form-select { appearance: none; cursor: pointer; }
.form-select option { background: var(--navy-mid); color: var(--white); }
.form-textarea { resize: vertical; min-height: 100px; }

.form-input.error, .form-select.error { border-color: #e05555; }
.form-error { font-size: 0.78rem; color: #e05555; margin-top: 0.25rem; display: none; }
.form-error.visible { display: block; }

.form-submit-btn {
  width: 100%;
  padding: 1rem;
  font-size: 1rem;
  margin-top: 0.5rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem;
}
.form-success.visible { display: block; }
.form-success h3 { color: var(--green); margin-bottom: 0.75rem; }

/* Support contact */
.support-contact-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2rem;
  position: sticky;
  top: 90px;
}
.support-region {
  padding: 1rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.support-region:last-child { border-bottom: none; }
.support-region h5 { margin-bottom: 0.35rem; font-size: 0.9rem; }
.support-region p { font-size: 0.82rem; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: rgba(21, 41, 90, 0.98);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(108,194,74,0.3);
  padding: 1.25rem 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.cookie-text { flex: 1; min-width: 280px; }
.cookie-text h5 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.cookie-text p { font-size: 0.8rem; }
.cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }

/* ===== COMPLIANCE CTA ===== */
.compliance-cta-section {
  background: linear-gradient(135deg, rgba(108,194,74,0.08) 0%, rgba(21,41,90,0.5) 100%);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
  margin-top: 2rem;
}
.compliance-cta-section h3 { margin-bottom: 1rem; }
.compliance-cta-section p { max-width: 560px; margin: 0 auto 2rem; }

/* ===== FOOTER ===== */
.footer {
  background: var(--navy-dark);
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand h3 { font-size: 1.25rem; margin-bottom: 0.75rem; }
.footer-brand p { font-size: 0.875rem; max-width: 260px; margin-bottom: 1.5rem; }

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.footer-links a {
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--green); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p { font-size: 0.8rem; }

.footer-login-portals {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-login-portals a {
  font-size: 0.8rem;
  color: var(--text-muted);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  transition: all 0.2s;
}
.footer-login-portals a:hover { color: var(--green); border-color: rgba(108,194,74,0.3); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .demo-layout { grid-template-columns: 1fr; }
  .support-contact-card { position: static; }
  .culture-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta .btn-outline { display: none; }
  .hamburger { display: flex; }

  .nav-mobile-menu {
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: var(--navy-mid);
    padding: 1.5rem;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    display: none;
    flex-direction: column;
    gap: 0.5rem;
    z-index: 999;
  }
  .nav-mobile-menu.open { display: flex; }
  .nav-mobile-menu a {
    display: block;
    padding: 0.75rem 1rem;
    color: rgba(255,255,255,0.8);
    border-radius: 6px;
    font-size: 0.95rem;
  }
  .nav-mobile-menu a:hover { background: rgba(255,255,255,0.06); color: var(--white); }
  .nav-mobile-menu .mobile-section-title {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    padding: 0.5rem 1rem 0.25rem;
  }

  .hero-stats { flex-direction: column; gap: 1.5rem; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .diagram-pillars { grid-template-columns: 1fr; }
  .diagram-pillars::before { display: none; }
  .soc-badges { grid-template-columns: 1fr; }
  .integration-tab-grid { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .lifecycle-tracks { grid-template-columns: 1fr; }
  .etl-benefits-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .tabs-nav { overflow-x: auto; }
  .lifecycle-flow { flex-direction: column; align-items: center; }
  .lifecycle-arrow { transform: rotate(90deg); }
  .renewables-inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.25rem; }
  .section { padding: 3.5rem 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}

/* WellStream Platform — Shared Styles */
:root {
  --navy: #15295A;
  --navy-dark: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #1e3a6e;
  --green: #6CC24A;
  --green-light: #7dd95a;
  --gray-dark: #3C424B;
  --gray-mid: #5a6270;
  --gray-light: #8a9ab0;
  --white: #ffffff;
  --off-white: #f0f4f8;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --text-muted: #9aaec4;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--navy-dark);
  color: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.2rem; }

p { color: var(--text-muted); line-height: 1.8; }

a { color: var(--green); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--green-light); }

.section-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.75rem;
  display: block;
}

/* ===== LAYOUT ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.section { padding: 5rem 0; }
.section-dark { background: var(--navy-dark); }
.section-mid { background: var(--navy-mid); }
.section-navy { background: var(--navy); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 4px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  text-decoration: none;
}

.btn-primary {
  background: var(--green);
  color: var(--navy-dark);
}
.btn-primary:hover { background: var(--green-light); color: var(--navy-dark); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(108,194,74,0.35); }

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}
.btn-outline:hover { border-color: var(--green); color: var(--green); background: rgba(108,194,74,0.08); }

.btn-ghost {
  background: transparent;
  color: var(--green);
  padding-left: 0;
}
.btn-ghost:hover { color: var(--green-light); }
.btn-ghost::after { content: ' →'; }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.3s;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--white);
}

.nav-logo-mark {
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1rem;
  color: var(--navy-dark);
}

.nav-logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.nav-logo-text span { color: var(--green); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
}

.nav-links li { position: relative; }

.nav-links a {
  color: rgba(255,255,255,0.8);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 0.875rem;
  border-radius: 4px;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.nav-links a:hover { color: var(--white); background: rgba(255,255,255,0.06); }

.nav-dropdown-trigger::after { content: ' ▾'; font-size: 0.7rem; opacity: 0.7; }

.nav-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}

.nav-links li:hover .nav-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown a {
  display: block;
  padding: 0.6rem 1rem;
  color: rgba(255,255,255,0.75);
  font-size: 0.85rem;
  border-radius: 4px;
}
.nav-dropdown a:hover { color: var(--white); background: rgba(108,194,74,0.12); }

.nav-cta { display: flex; align-items: center; gap: 1rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.hamburger span { display: block; width: 24px; height: 2px; background: var(--white); border-radius: 2px; transition: all 0.3s; }

/* ===== HERO ===== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--navy-dark) 0%, #0a1628 50%, #0d1f3c 100%);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
}

.hero-glow {
  position: absolute;
  width: 800px;
  height: 800px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
  top: -200px;
  right: -200px;
  pointer-events: none;
}

.hero-content { position: relative; z-index: 1; padding-top: 68px; }
.hero .container { padding-top: 4rem; padding-bottom: 4rem; }

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.3);
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.4rem 1rem;
  border-radius: 100px;
  margin-bottom: 1.5rem;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.85) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  max-width: 580px;
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: 2.5rem;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 3rem;
  margin-top: 4rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.hero-stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}
.hero-stat-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.25rem; }

/* Sub-page hero */
.page-hero {
  padding: 8rem 0 4rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.03) 1px, transparent 1px);
  background-size: 50px 50px;
}
.page-hero .container { position: relative; z-index: 1; }
.page-hero h1 { max-width: 700px; margin-bottom: 1rem; }
.page-hero p { max-width: 580px; font-size: 1.1rem; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(90deg, var(--green) 0%, #4a9932 100%);
  padding: 1.25rem 0;
}
.featured-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.featured-banner-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.6);
}
.featured-banner-product {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy-dark);
}
.featured-banner-tagline { color: rgba(0,0,0,0.7); font-size: 0.9rem; }
.featured-banner .btn {
  background: var(--navy-dark);
  color: var(--white);
  font-size: 0.85rem;
  padding: 0.6rem 1.5rem;
}
.featured-banner .btn:hover { background: var(--navy); }

/* ===== CARDS ===== */
.card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  padding: 2rem;
  transition: all 0.3s;
}
.card:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(108,194,74,0.25);
  transform: translateY(-3px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--green);
  font-size: 1.4rem;
}

.card h4 { margin-bottom: 0.5rem; }
.card p { font-size: 0.9rem; }

/* ===== GRIDS ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* ===== SECTION HEADER ===== */
.section-header { margin-bottom: 3.5rem; }
.section-header.centered { text-align: center; }
.section-header h2 { margin-bottom: 1rem; }
.section-header p { max-width: 640px; font-size: 1.05rem; }
.section-header.centered p { margin: 0 auto; }

/* ===== USE CASES ===== */
.use-case-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.75rem;
  cursor: pointer;
  transition: all 0.3s;
  position: relative;
  overflow: hidden;
}
.use-case-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform 0.3s;
}
.use-case-card:hover::before { transform: scaleX(1); }
.use-case-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
}
.use-case-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.use-case-card h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.use-case-card p { font-size: 0.85rem; }

/* ===== PLATFORM DIAGRAM ===== */
.platform-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  margin-top: 2rem;
}

.diagram-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  position: relative;
}

.diagram-pillars::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(108,194,74,0.4), rgba(108,194,74,0.4), transparent);
  transform: translateY(-50%);
  z-index: 0;
}

.pillar {
  text-align: center;
  padding: 2rem 1.5rem;
  position: relative;
  z-index: 1;
}

.pillar-node {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--navy-dark);
  border: 3px solid var(--green);
  margin: 0 auto 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  position: relative;
  box-shadow: 0 0 24px rgba(108,194,74,0.25);
}

.pillar-node::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(108,194,74,0.2);
}

.pillar h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.pillar p { font-size: 0.85rem; }

.diagram-center-label {
  text-align: center;
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.diagram-center-label h3 { color: var(--white); }
.diagram-center-label span {
  display: inline-block;
  margin-top: 0.5rem;
  background: rgba(108,194,74,0.12);
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.3rem 1rem;
  border-radius: 100px;
  letter-spacing: 0.05em;
}

/* ===== INDUSTRY TABS ===== */
.tabs-container { margin-top: 1rem; }
.tabs-nav {
  display: flex;
  gap: 0.25rem;
  background: rgba(255,255,255,0.04);
  border-radius: 8px;
  padding: 0.35rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.tab-btn {
  padding: 0.6rem 1.25rem;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,0.06); }
.tab-btn.active {
  background: var(--green);
  color: var(--navy-dark);
  font-weight: 700;
}

.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.industry-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}
.industry-content h3 { margin-bottom: 1rem; }
.industry-content p { margin-bottom: 1.5rem; }

.industry-products {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.industry-product-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 6px;
  padding: 0.5rem 0.875rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
}

/* ===== CULTURE SECTION ===== */
.culture-section {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.07) 0%, transparent 70%);
  bottom: -200px; left: -100px;
}

.culture-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.culture-visual {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem 2rem;
  text-align: center;
  position: relative;
}

.culture-stat-ring {
  width: 160px;
  height: 160px;
  margin: 0 auto 1.5rem;
  position: relative;
}

.culture-stat-ring svg { transform: rotate(-90deg); }
.culture-stat-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-top: 1.5rem;
}
.client-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.15);
  border-radius: 6px;
  padding: 0.4rem;
  font-size: 0.7rem;
  color: var(--green);
  text-align: center;
  font-weight: 600;
}

/* ===== RENEWABLES CTA ===== */
.renewables-cta {
  background: linear-gradient(135deg, #0d3b1e 0%, #0a2d16 100%);
  border-top: 1px solid rgba(108,194,74,0.2);
  border-bottom: 1px solid rgba(108,194,74,0.2);
}
.renewables-inner {
  display: flex;
  align-items: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.renewables-icon {
  font-size: 4rem;
  flex-shrink: 0;
}
.renewables-text { flex: 1; min-width: 280px; }
.renewables-text h3 { color: var(--green); margin-bottom: 0.75rem; }

/* ===== PLATFORM BENEFITS ===== */
.benefit-item {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background 0.2s;
}
.benefit-item:last-child { border-bottom: none; }
.benefit-item:hover { background: rgba(255,255,255,0.02); border-radius: 8px; }

.benefit-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}
.benefit-text h4 { margin-bottom: 0.375rem; }
.benefit-text p { font-size: 0.9rem; }

/* ===== STATS CIRCLES ===== */
.stats-section { padding: 4rem 0; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.stat-circle-wrapper {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  transition: all 0.3s;
}
.stat-circle-wrapper:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
}

.stat-circle {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  margin: 0 auto 1.5rem;
  background: conic-gradient(var(--green) var(--pct), rgba(255,255,255,0.06) 0deg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.stat-circle::before {
  content: '';
  position: absolute;
  inset: 12px;
  border-radius: 50%;
  background: var(--navy-dark);
}

.stat-circle-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--white);
  display: block;
}

.stat-circle-label { font-size: 1rem; font-weight: 600; margin-bottom: 0.375rem; }
.stat-circle-desc { font-size: 0.85rem; color: var(--text-muted); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline-item {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline-item:last-child { border-bottom: none; }

.timeline-duration {
  min-width: 130px;
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--green);
}

.timeline-info { flex: 1; }
.timeline-info h4 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.timeline-info p { font-size: 0.85rem; }

.timeline-bar-wrapper {
  flex: 2;
  max-width: 400px;
}
.timeline-bar-bg {
  background: rgba(255,255,255,0.06);
  border-radius: 100px;
  height: 8px;
  overflow: hidden;
}
.timeline-bar-fill {
  height: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, var(--green), var(--green-light));
  transition: width 1s ease;
}

/* ===== ACCORDION ===== */
.accordion { border-radius: 12px; overflow: hidden; border: 1px solid rgba(255,255,255,0.08); }

.accordion-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: rgba(255,255,255,0.02);
  border: none;
  color: var(--white);
  font-size: 1.05rem;
  font-weight: 600;
  padding: 1.5rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: background 0.2s;
  font-family: inherit;
  text-align: left;
}
.accordion-header:hover { background: rgba(255,255,255,0.05); }
.accordion-header.open { background: rgba(108,194,74,0.08); color: var(--green); }

.accordion-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.3s;
  font-size: 0.85rem;
}
.accordion-header.open .accordion-icon { transform: rotate(45deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}
.accordion-body-inner {
  padding: 0 2rem 1.75rem;
  color: var(--text-muted);
  line-height: 1.8;
}

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  position: relative;
  overflow: hidden;
}

.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
}

.lifecycle-step {
  text-align: center;
  padding: 1.5rem;
  min-width: 140px;
}

.lifecycle-step-node {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 2px solid var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin: 0 auto 1rem;
  background: rgba(108,194,74,0.08);
  position: relative;
}

.lifecycle-arrow {
  color: rgba(108,194,74,0.5);
  font-size: 1.5rem;
  flex-shrink: 0;
  padding: 0 0.5rem;
  align-self: center;
  margin-bottom: 2.5rem;
}

.lifecycle-step h5 { font-size: 0.85rem; margin-bottom: 0.25rem; }
.lifecycle-step p { font-size: 0.75rem; }

.lifecycle-tracks {
  margin-top: 3rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 2.5rem;
}
.lifecycle-track {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
}
.lifecycle-track-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.lifecycle-track h4 { font-size: 0.95rem; margin-bottom: 0.5rem; }
.lifecycle-track p { font-size: 0.8rem; }

/* ===== TESTIMONIALS ===== */
.testimonial-carousel { position: relative; overflow: hidden; }

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--white);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '"';
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
  font-size: 5rem;
  color: rgba(108,194,74,0.15);
  font-style: normal;
  line-height: 1;
}

.testimonial-author {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--green);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.carousel-dot.active { background: var(--green); transform: scale(1.3); }

/* ===== SECURITY ===== */
.security-feature {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  transition: all 0.3s;
  margin-bottom: 1rem;
}
.security-feature:hover {
  border-color: rgba(108,194,74,0.25);
  background: rgba(108,194,74,0.04);
  transform: translateX(4px);
}
.security-feature:last-child { margin-bottom: 0; }

.security-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  color: var(--green);
}

.security-text h4 { margin-bottom: 0.4rem; }
.security-text p { font-size: 0.9rem; }

.soc-badges {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.soc-badge {
  background: rgba(255,255,255,0.03);
  border: 2px solid rgba(108,194,74,0.3);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  text-align: center;
}
.soc-badge-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.soc-badge p { font-size: 0.875rem; }

/* ===== INTEGRATION TABS ===== */
.integration-tabs-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}

.integration-tab-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.integration-visual {
  background: var(--navy-dark);
  border-radius: 12px;
  padding: 2rem;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.06);
}

.etl-flow {
  width: 100%;
}
.etl-block {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  text-align: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.etl-arrow {
  text-align: center;
  color: rgba(108,194,74,0.5);
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.api-endpoints {
  width: 100%;
}
.api-endpoint {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.875rem;
  background: rgba(255,255,255,0.03);
  border-radius: 6px;
  margin-bottom: 0.5rem;
  font-size: 0.8rem;
  font-family: 'Courier New', monospace;
}
.api-method {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 3px;
  min-width: 44px;
  text-align: center;
}
.api-method.get { background: rgba(108,194,74,0.2); color: var(--green); }
.api-method.post { background: rgba(0,180,216,0.2); color: var(--accent-blue); }
.api-endpoint-path { color: var(--text-muted); }

.dashboard-preview {
  width: 100%;
}
.dashboard-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.dashboard-widget {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 8px;
  padding: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}
.dashboard-widget-value {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.2rem;
}

/* ===== ETL BENEFITS ===== */
.etl-benefits-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.25rem; }
.etl-benefit {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: all 0.3s;
}
.etl-benefit:hover { border-color: rgba(108,194,74,0.25); background: rgba(108,194,74,0.04); }
.etl-check {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.875rem;
  flex-shrink: 0;
  margin-top: 2px;
}
.etl-benefit h4 { font-size: 0.95rem; margin-bottom: 0.35rem; }
.etl-benefit p { font-size: 0.85rem; }

/* ===== DEMO FORM ===== */
.demo-layout {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 4rem;
  align-items: start;
}

.demo-form-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2.5rem;
}

.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
.form-field { display: flex; flex-direction: column; gap: 0.4rem; }
.form-field.full { grid-column: 1 / -1; }

.form-label {
  font-size: 0.825rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  letter-spacing: 0.02em;
}

.form-input, .form-select, .form-textarea {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  color: var(--white);
  font-size: 0.9rem;
  padding: 0.75rem 1rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  font-family: inherit;
  width: 100%;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(108,194,74,0.12);
}
.form-input::placeholder, .form-textarea::placeholder { color: var(--text-muted); }
.form-select { appearance: none; cursor: pointer; }
.form-select option { background: var(--navy-mid); color: var(--white); }
.form-textarea { resize: vertical; min-height: 100px; }

.form-input.error, .form-select.error { border-color: #e05555; }
.form-error { font-size: 0.78rem; color: #e05555; margin-top: 0.25rem; display: none; }
.form-error.visible { display: block; }

.form-submit-btn {
  width: 100%;
  padding: 1rem;
  font-size: 1rem;
  margin-top: 0.5rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem;
}
.form-success.visible { display: block; }
.form-success h3 { color: var(--green); margin-bottom: 0.75rem; }

/* Support contact */
.support-contact-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2rem;
  position: sticky;
  top: 90px;
}
.support-region {
  padding: 1rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.support-region:last-child { border-bottom: none; }
.support-region h5 { margin-bottom: 0.35rem; font-size: 0.9rem; }
.support-region p { font-size: 0.82rem; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: rgba(21, 41, 90, 0.98);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(108,194,74,0.3);
  padding: 1.25rem 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.cookie-text { flex: 1; min-width: 280px; }
.cookie-text h5 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.cookie-text p { font-size: 0.8rem; }
.cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }

/* ===== COMPLIANCE CTA ===== */
.compliance-cta-section {
  background: linear-gradient(135deg, rgba(108,194,74,0.08) 0%, rgba(21,41,90,0.5) 100%);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
  margin-top: 2rem;
}
.compliance-cta-section h3 { margin-bottom: 1rem; }
.compliance-cta-section p { max-width: 560px; margin: 0 auto 2rem; }

/* ===== FOOTER ===== */
.footer {
  background: var(--navy-dark);
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand h3 { font-size: 1.25rem; margin-bottom: 0.75rem; }
.footer-brand p { font-size: 0.875rem; max-width: 260px; margin-bottom: 1.5rem; }

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.footer-links a {
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--green); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p { font-size: 0.8rem; }

.footer-login-portals {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-login-portals a {
  font-size: 0.8rem;
  color: var(--text-muted);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  transition: all 0.2s;
}
.footer-login-portals a:hover { color: var(--green); border-color: rgba(108,194,74,0.3); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .demo-layout { grid-template-columns: 1fr; }
  .support-contact-card { position: static; }
  .culture-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta .btn-outline { display: none; }
  .hamburger { display: flex; }

  .nav-mobile-menu {
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: var(--navy-mid);
    padding: 1.5rem;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    display: none;
    flex-direction: column;
    gap: 0.5rem;
    z-index: 999;
  }
  .nav-mobile-menu.open { display: flex; }
  .nav-mobile-menu a {
    display: block;
    padding: 0.75rem 1rem;
    color: rgba(255,255,255,0.8);
    border-radius: 6px;
    font-size: 0.95rem;
  }
  .nav-mobile-menu a:hover { background: rgba(255,255,255,0.06); color: var(--white); }
  .nav-mobile-menu .mobile-section-title {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    padding: 0.5rem 1rem 0.25rem;
  }

  .hero-stats { flex-direction: column; gap: 1.5rem; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .diagram-pillars { grid-template-columns: 1fr; }
  .diagram-pillars::before { display: none; }
  .soc-badges { grid-template-columns: 1fr; }
  .integration-tab-grid { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .lifecycle-tracks { grid-template-columns: 1fr; }
  .etl-benefits-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .tabs-nav { overflow-x: auto; }
  .lifecycle-flow { flex-direction: column; align-items: center; }
  .lifecycle-arrow { transform: rotate(90deg); }
  .renewables-inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.25rem; }
  .section { padding: 3.5rem 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}

raw_arguments.content:
/* WellStream Platform — Shared Styles */
:root {
  --navy: #15295A;
  --navy-dark: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #1e3a6e;
  --green: #6CC24A;
  --green-light: #7dd95a;
  --gray-dark: #3C424B;
  --gray-mid: #5a6270;
  --gray-light: #8a9ab0;
  --white: #ffffff;
  --off-white: #f0f4f8;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --text-muted: #9aaec4;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--navy-dark);
  color: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.2rem; }

p { color: var(--text-muted); line-height: 1.8; }

a { color: var(--green); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--green-light); }

.section-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.75rem;
  display: block;
}

/* ===== LAYOUT ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.section { padding: 5rem 0; }
.section-dark { background: var(--navy-dark); }
.section-mid { background: var(--navy-mid); }
.section-navy { background: var(--navy); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 4px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  text-decoration: none;
}

.btn-primary {
  background: var(--green);
  color: var(--navy-dark);
}
.btn-primary:hover { background: var(--green-light); color: var(--navy-dark); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(108,194,74,0.35); }

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}
.btn-outline:hover { border-color: var(--green); color: var(--green); background: rgba(108,194,74,0.08); }

.btn-ghost {
  background: transparent;
  color: var(--green);
  padding-left: 0;
}
.btn-ghost:hover { color: var(--green-light); }
.btn-ghost::after { content: ' →'; }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.3s;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--white);
}

.nav-logo-mark {
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 1rem;
  color: var(--navy-dark);
}

.nav-logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.nav-logo-text span { color: var(--green); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
}

.nav-links li { position: relative; }

.nav-links a {
  color: rgba(255,255,255,0.8);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 0.875rem;
  border-radius: 4px;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.nav-links a:hover { color: var(--white); background: rgba(255,255,255,0.06); }

.nav-dropdown-trigger::after { content: ' ▾'; font-size: 0.7rem; opacity: 0.7; }

.nav-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}

.nav-links li:hover .nav-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown a {
  display: block;
  padding: 0.6rem 1rem;
  color: rgba(255,255,255,0.75);
  font-size: 0.85rem;
  border-radius: 4px;
}
.nav-dropdown a:hover { color: var(--white); background: rgba(108,194,74,0.12); }

.nav-cta { display: flex; align-items: center; gap: 1rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.hamburger span { display: block; width: 24px; height: 2px; background: var(--white); border-radius: 2px; transition: all 0.3s; }

/* ===== HERO ===== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--navy-dark) 0%, #0a1628 50%, #0d1f3c 100%);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
}

.hero-glow {
  position: absolute;
  width: 800px;
  height: 800px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
  top: -200px;
  right: -200px;
  pointer-events: none;
}

.hero-content { position: relative; z-index: 1; padding-top: 68px; }
.hero .container { padding-top: 4rem; padding-bottom: 4rem; }

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.3);
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.4rem 1rem;
  border-radius: 100px;
  margin-bottom: 1.5rem;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.85) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  max-width: 580px;
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: 2.5rem;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

.hero-stats {
  display: flex;
  gap: 3rem;
  margin-top: 4rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.hero-stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}
.hero-stat-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.25rem; }

/* Sub-page hero */
.page-hero {
  padding: 8rem 0 4rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(108,194,74,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(108,194,74,0.03) 1px, transparent 1px);
  background-size: 50px 50px;
}
.page-hero .container { position: relative; z-index: 1; }
.page-hero h1 { max-width: 700px; margin-bottom: 1rem; }
.page-hero p { max-width: 580px; font-size: 1.1rem; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(90deg, var(--green) 0%, #4a9932 100%);
  padding: 1.25rem 0;
}
.featured-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.featured-banner-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(0,0,0,0.6);
}
.featured-banner-product {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy-dark);
}
.featured-banner-tagline { color: rgba(0,0,0,0.7); font-size: 0.9rem; }
.featured-banner .btn {
  background: var(--navy-dark);
  color: var(--white);
  font-size: 0.85rem;
  padding: 0.6rem 1.5rem;
}
.featured-banner .btn:hover { background: var(--navy); }

/* ===== CARDS ===== */
.card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  padding: 2rem;
  transition: all 0.3s;
}
.card:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(108,194,74,0.25);
  transform: translateY(-3px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--green);
  font-size: 1.4rem;
}

.card h4 { margin-bottom: 0.5rem; }
.card p { font-size: 0.9rem; }

/* ===== GRIDS ===== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* ===== SECTION HEADER ===== */
.section-header { margin-bottom: 3.5rem; }
.section-header.centered { text-align: center; }
.section-header h2 { margin-bottom: 1rem; }
.section-header p { max-width: 640px; font-size: 1.05rem; }
.section-header.centered p { margin: 0 auto; }

/* ===== USE CASES ===== */
.use-case-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.75rem;
  cursor: pointer;
  transition: all 0.3s;
  position: relative;
  overflow: hidden;
}
.use-case-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform 0.3s;
}
.use-case-card:hover::before { transform: scaleX(1); }
.use-case-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
}
.use-case-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.use-case-card h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.use-case-card p { font-size: 0.85rem; }

/* ===== PLATFORM DIAGRAM ===== */
.platform-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  margin-top: 2rem;
}

.diagram-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  position: relative;
}

.diagram-pillars::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(108,194,74,0.4), rgba(108,194,74,0.4), transparent);
  transform: translateY(-50%);
  z-index: 0;
}

.pillar {
  text-align: center;
  padding: 2rem 1.5rem;
  position: relative;
  z-index: 1;
}

.pillar-node {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--navy-dark);
  border: 3px solid var(--green);
  margin: 0 auto 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  position: relative;
  box-shadow: 0 0 24px rgba(108,194,74,0.25);
}

.pillar-node::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(108,194,74,0.2);
}

.pillar h4 { margin-bottom: 0.5rem; font-size: 1rem; }
.pillar p { font-size: 0.85rem; }

.diagram-center-label {
  text-align: center;
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.diagram-center-label h3 { color: var(--white); }
.diagram-center-label span {
  display: inline-block;
  margin-top: 0.5rem;
  background: rgba(108,194,74,0.12);
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.3rem 1rem;
  border-radius: 100px;
  letter-spacing: 0.05em;
}

/* ===== INDUSTRY TABS ===== */
.tabs-container { margin-top: 1rem; }
.tabs-nav {
  display: flex;
  gap: 0.25rem;
  background: rgba(255,255,255,0.04);
  border-radius: 8px;
  padding: 0.35rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.tab-btn {
  padding: 0.6rem 1.25rem;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,0.06); }
.tab-btn.active {
  background: var(--green);
  color: var(--navy-dark);
  font-weight: 700;
}

.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.industry-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}
.industry-content h3 { margin-bottom: 1rem; }
.industry-content p { margin-bottom: 1.5rem; }

.industry-products {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.industry-product-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 6px;
  padding: 0.5rem 0.875rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
}

/* ===== CULTURE SECTION ===== */
.culture-section {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
  position: relative;
  overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(108,194,74,0.07) 0%, transparent 70%);
  bottom: -200px; left: -100px;
}

.culture-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.culture-visual {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem 2rem;
  text-align: center;
  position: relative;
}

.culture-stat-ring {
  width: 160px;
  height: 160px;
  margin: 0 auto 1.5rem;
  position: relative;
}

.culture-stat-ring svg { transform: rotate(-90deg); }
.culture-stat-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-top: 1.5rem;
}
.client-tag {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.15);
  border-radius: 6px;
  padding: 0.4rem;
  font-size: 0.7rem;
  color: var(--green);
  text-align: center;
  font-weight: 600;
}

/* ===== RENEWABLES CTA ===== */
.renewables-cta {
  background: linear-gradient(135deg, #0d3b1e 0%, #0a2d16 100%);
  border-top: 1px solid rgba(108,194,74,0.2);
  border-bottom: 1px solid rgba(108,194,74,0.2);
}
.renewables-inner {
  display: flex;
  align-items: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.renewables-icon {
  font-size: 4rem;
  flex-shrink: 0;
}
.renewables-text { flex: 1; min-width: 280px; }
.renewables-text h3 { color: var(--green); margin-bottom: 0.75rem; }

/* ===== PLATFORM BENEFITS ===== */
.benefit-item {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background 0.2s;
}
.benefit-item:last-child { border-bottom: none; }
.benefit-item:hover { background: rgba(255,255,255,0.02); border-radius: 8px; }

.benefit-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}
.benefit-text h4 { margin-bottom: 0.375rem; }
.benefit-text p { font-size: 0.9rem; }

/* ===== STATS CIRCLES ===== */
.stats-section { padding: 4rem 0; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.stat-circle-wrapper {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  transition: all 0.3s;
}
.stat-circle-wrapper:hover {
  border-color: rgba(108,194,74,0.3);
  background: rgba(255,255,255,0.05);
  transform: translateY(-4px);
}

.stat-circle {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  margin: 0 auto 1.5rem;
  background: conic-gradient(var(--green) var(--pct), rgba(255,255,255,0.06) 0deg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.stat-circle::before {
  content: '';
  position: absolute;
  inset: 12px;
  border-radius: 50%;
  background: var(--navy-dark);
}

.stat-circle-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--white);
  display: block;
}

.stat-circle-label { font-size: 1rem; font-weight: 600; margin-bottom: 0.375rem; }
.stat-circle-desc { font-size: 0.85rem; color: var(--text-muted); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline-item {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline-item:last-child { border-bottom: none; }

.timeline-duration {
  min-width: 130px;
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--green);
}

.timeline-info { flex: 1; }
.timeline-info h4 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.timeline-info p { font-size: 0.85rem; }

.timeline-bar-wrapper {
  flex: 2;
  max-width: 400px;
}
.timeline-bar-bg {
  background: rgba(255,255,255,0.06);
  border-radius: 100px;
  height: 8px;
  overflow: hidden;
}
.timeline-bar-fill {
  height: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, var(--green), var(--green-light));
  transition: width 1s ease;
}

/* ===== ACCORDION ===== */
.accordion { border-radius: 12px; overflow: hidden; border: 1px solid rgba(255,255,255,0.08); }

.accordion-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: rgba(255,255,255,0.02);
  border: none;
  color: var(--white);
  font-size: 1.05rem;
  font-weight: 600;
  padding: 1.5rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: background 0.2s;
  font-family: inherit;
  text-align: left;
}
.accordion-header:hover { background: rgba(255,255,255,0.05); }
.accordion-header.open { background: rgba(108,194,74,0.08); color: var(--green); }

.accordion-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.3s;
  font-size: 0.85rem;
}
.accordion-header.open .accordion-icon { transform: rotate(45deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}
.accordion-body-inner {
  padding: 0 2rem 1.75rem;
  color: var(--text-muted);
  line-height: 1.8;
}

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  background: var(--navy-mid);
  border-radius: 16px;
  padding: 3rem;
  position: relative;
  overflow: hidden;
}

.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
}

.lifecycle-step {
  text-align: center;
  padding: 1.5rem;
  min-width: 140px;
}

.lifecycle-step-node {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 2px solid var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin: 0 auto 1rem;
  background: rgba(108,194,74,0.08);
  position: relative;
}

.lifecycle-arrow {
  color: rgba(108,194,74,0.5);
  font-size: 1.5rem;
  flex-shrink: 0;
  padding: 0 0.5rem;
  align-self: center;
  margin-bottom: 2.5rem;
}

.lifecycle-step h5 { font-size: 0.85rem; margin-bottom: 0.25rem; }
.lifecycle-step p { font-size: 0.75rem; }

.lifecycle-tracks {
  margin-top: 3rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 2.5rem;
}
.lifecycle-track {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
}
.lifecycle-track-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.lifecycle-track h4 { font-size: 0.95rem; margin-bottom: 0.5rem; }
.lifecycle-track p { font-size: 0.8rem; }

/* ===== TESTIMONIALS ===== */
.testimonial-carousel { position: relative; overflow: hidden; }

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  color: var(--white);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '"';
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
  font-size: 5rem;
  color: rgba(108,194,74,0.15);
  font-style: normal;
  line-height: 1;
}

.testimonial-author {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--green);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}
.carousel-dot.active { background: var(--green); transform: scale(1.3); }

/* ===== SECURITY ===== */
.security-feature {
  display: flex;
  gap: 1.5rem;
  align-items: flex-start;
  padding: 1.75rem;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  transition: all 0.3s;
  margin-bottom: 1rem;
}
.security-feature:hover {
  border-color: rgba(108,194,74,0.25);
  background: rgba(108,194,74,0.04);
  transform: translateX(4px);
}
.security-feature:last-child { margin-bottom: 0; }

.security-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: rgba(108,194,74,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  color: var(--green);
}

.security-text h4 { margin-bottom: 0.4rem; }
.security-text p { font-size: 0.9rem; }

.soc-badges {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.soc-badge {
  background: rgba(255,255,255,0.03);
  border: 2px solid rgba(108,194,74,0.3);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  text-align: center;
}
.soc-badge-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.soc-badge p { font-size: 0.875rem; }

/* ===== INTEGRATION TABS ===== */
.integration-tabs-content {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 12px;
  padding: 2.5rem;
}

.integration-tab-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.integration-visual {
  background: var(--navy-dark);
  border-radius: 12px;
  padding: 2rem;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.06);
}

.etl-flow {
  width: 100%;
}
.etl-block {
  background: rgba(108,194,74,0.08);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  text-align: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green);
  margin-bottom: 0.5rem;
}
.etl-arrow {
  text-align: center;
  color: rgba(108,194,74,0.5);
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.api-endpoints {
  width: 100%;
}
.api-endpoint {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.875rem;
  background: rgba(255,255,255,0.03);
  border-radius: 6px;
  margin-bottom: 0.5rem;
  font-size: 0.8rem;
  font-family: 'Courier New', monospace;
}
.api-method {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 3px;
  min-width: 44px;
  text-align: center;
}
.api-method.get { background: rgba(108,194,74,0.2); color: var(--green); }
.api-method.post { background: rgba(0,180,216,0.2); color: var(--accent-blue); }
.api-endpoint-path { color: var(--text-muted); }

.dashboard-preview {
  width: 100%;
}
.dashboard-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}
.dashboard-widget {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 8px;
  padding: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}
.dashboard-widget-value {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 0.2rem;
}

/* ===== ETL BENEFITS ===== */
.etl-benefits-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.25rem; }
.etl-benefit {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 1.5rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: all 0.3s;
}
.etl-benefit:hover { border-color: rgba(108,194,74,0.25); background: rgba(108,194,74,0.04); }
.etl-check {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.875rem;
  flex-shrink: 0;
  margin-top: 2px;
}
.etl-benefit h4 { font-size: 0.95rem; margin-bottom: 0.35rem; }
.etl-benefit p { font-size: 0.85rem; }

/* ===== DEMO FORM ===== */
.demo-layout {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 4rem;
  align-items: start;
}

.demo-form-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2.5rem;
}

.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; }
.form-field { display: flex; flex-direction: column; gap: 0.4rem; }
.form-field.full { grid-column: 1 / -1; }

.form-label {
  font-size: 0.825rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  letter-spacing: 0.02em;
}

.form-input, .form-select, .form-textarea {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 6px;
  color: var(--white);
  font-size: 0.9rem;
  padding: 0.75rem 1rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  font-family: inherit;
  width: 100%;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(108,194,74,0.12);
}
.form-input::placeholder, .form-textarea::placeholder { color: var(--text-muted); }
.form-select { appearance: none; cursor: pointer; }
.form-select option { background: var(--navy-mid); color: var(--white); }
.form-textarea { resize: vertical; min-height: 100px; }

.form-input.error, .form-select.error { border-color: #e05555; }
.form-error { font-size: 0.78rem; color: #e05555; margin-top: 0.25rem; display: none; }
.form-error.visible { display: block; }

.form-submit-btn {
  width: 100%;
  padding: 1rem;
  font-size: 1rem;
  margin-top: 0.5rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem;
}
.form-success.visible { display: block; }
.form-success h3 { color: var(--green); margin-bottom: 0.75rem; }

/* Support contact */
.support-contact-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2rem;
  position: sticky;
  top: 90px;
}
.support-region {
  padding: 1rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.support-region:last-child { border-bottom: none; }
.support-region h5 { margin-bottom: 0.35rem; font-size: 0.9rem; }
.support-region p { font-size: 0.82rem; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: rgba(21, 41, 90, 0.98);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(108,194,74,0.3);
  padding: 1.25rem 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.cookie-text { flex: 1; min-width: 280px; }
.cookie-text h5 { margin-bottom: 0.25rem; font-size: 0.95rem; }
.cookie-text p { font-size: 0.8rem; }
.cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }

/* ===== COMPLIANCE CTA ===== */
.compliance-cta-section {
  background: linear-gradient(135deg, rgba(108,194,74,0.08) 0%, rgba(21,41,90,0.5) 100%);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px;
  padding: 3rem;
  text-align: center;
  margin-top: 2rem;
}
.compliance-cta-section h3 { margin-bottom: 1rem; }
.compliance-cta-section p { max-width: 560px; margin: 0 auto 2rem; }

/* ===== FOOTER ===== */
.footer {
  background: var(--navy-dark);
  border-top: 1px solid rgba(255,255,255,0.07);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand h3 { font-size: 1.25rem; margin-bottom: 0.75rem; }
.footer-brand p { font-size: 0.875rem; max-width: 260px; margin-bottom: 1.5rem; }

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.footer-links a {
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--green); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p { font-size: 0.8rem; }

.footer-login-portals {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-login-portals a {
  font-size: 0.8rem;
  color: var(--text-muted);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  transition: all 0.2s;
}
.footer-login-portals a:hover { color: var(--green); border-color: rgba(108,194,74,0.3); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .demo-layout { grid-template-columns: 1fr; }
  .support-contact-card { position: static; }
  .culture-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta .btn-outline { display: none; }
  .hamburger { display: flex; }

  .nav-mobile-menu {
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: var(--navy-mid);
    padding: 1.5rem;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    display: none;
    flex-direction: column;
    gap: 0.5rem;
    z-index: 999;
  }
  .nav-mobile-menu.open { display: flex; }
  .nav-mobile-menu a {
    display: block;
    padding: 0.75rem 1rem;
    color: rgba(255,255,255,0.8);
    border-radius: 6px;
    font-size: 0.95rem;
  }
  .nav-mobile-menu a:hover { background: rgba(255,255,255,0.06); color: var(--white); }
  .nav-mobile-menu .mobile-section-title {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    padding: 0.5rem 1rem 0.25rem;
  }

  .hero-stats { flex-direction: column; gap: 1.5rem; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .diagram-pillars { grid-template-columns: 1fr; }
  .diagram-pillars::before { display: none; }
  .soc-badges { grid-template-columns: 1fr; }
  .integration-tab-grid { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .lifecycle-tracks { grid-template-columns: 1fr; }
  .etl-benefits-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .tabs-nav { overflow-x: auto; }
  .lifecycle-flow { flex-direction: column; align-items: center; }
  .lifecycle-arrow { transform: rotate(90deg); }
  .renewables-inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.25rem; }
  .section { padding: 3.5rem 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}
